// Map the incoming incident to a live callx402 action.
// Body: { incident_type, evidence?, txHash?, network?, operationId? }
const input = $input.first().json;
const MAP = {
  settlement_uncertain: 'resolve',
  paid_no_result: 'recover',
  retry_uncertain: 'diagnose',
  need_proof: 'evidence',
  need_explanation: 'explain',
  duplicate_payment_check: 'duplicate_payment_risk',
  pre_commit: 'preflight'
};
const action = MAP[input.incident_type];
if (!action) {
  throw new Error('unknown incident_type: ' + input.incident_type +
    '. Use one of: ' + Object.keys(MAP).join(', '));
}
const body = {};
if (input.evidence) body.evidence = input.evidence;
if (input.operationId) body.operationId = input.operationId;
if (input.txHash) {
  body.evidence = JSON.stringify({ txHash: input.txHash, network: input.network || 'base' });
}
const creditId = $env.CALLX402_CREDIT_ID || '';
if (creditId) body.credit_id = creditId;
return [{ action, body, incident_type: input.incident_type }];

// Fail-closed formatting: pass through what the rail returned,
// never invent a verdict.
const action = $('Map incident to action').item.json.action;
const result = $input.first().json;
return [{ action, status: 'executed', result }];

// No credential configured: emit payment instructions from the FREE
// live quote instead of invoking. The operator (or a wallet step) pays
// deliberately; this workflow never auto-pays.
const req = $('Map incident to action').item.json;
const q = $('Get live quote (free)').item.json;
const instructions = [
  'callx402 action \'' + req.action + '\' is paid on-demand.',
  'Live x402 quote: $' + q.quoted_price_usd + ' USDC on Base (quote ' +
    q.quote_id + ', expires ' + q.expires_at + ').',
  'To pay as an agent: POST https://payload-rail.fly.dev/v1/callx402/actions/' +
    req.action + ' with no auth -> x402 v2 402 (exact USDC amount, pay-to, ' +
    '300s window) -> pay from an authorized wallet -> retry with {txHash, quote_id}.',
  'To pay as a human: POST https://payload-rail.fly.dev/v1/callx402/checkout ' +
    '{"action":"' + req.action + '"} -> one-time Stripe checkout -> single-use credit.',
  'Or set VEYLINE_API_KEY / CALLX402_CREDIT_ID env vars and re-run: the ' +
    'action executes automatically.',
  'Free alternative: the local read-only MCP server / CLI covers diagnostics ' +
    'at zero cost (Payloadhq/callx402, node mcp/index.js).'
];
return [{ action: req.action, status: 'payment_required', instructions }];
